CREATE OR REPLACE FUNCTION public.batch_reassign_departed_staff_shifts(p_actor_auth_id uuid, p_start_at timestamp without time zone, p_from_user_id text, p_to_user_id text)
 RETURNS TABLE(processed_count integer, updated_count integer, deleted_count integer, failed_count integer, weekly_processed_count integer, weekly_updated_count integer, weekly_deleted_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_shift public.shift%rowtype;
  v_template public.shift_weekly_template%rowtype;
  v_entries jsonb;
  v_next jsonb;
  v_entry jsonb;
  v_user_id text;
  v_seen text[] := array[]::text[];
  v_target_exists boolean;
  v_count integer;
  v_updated integer := 0;
  v_deleted integer := 0;
  v_processed integer := 0;
  v_weekly_processed integer := 0;
  v_weekly_updated integer := 0;
  v_weekly_deleted integer := 0;
begin
  if p_start_at is null or nullif(btrim(p_from_user_id), '') is null or nullif(btrim(p_to_user_id), '') is null then
    raise exception '開始日時、変更元スタッフ、変更先スタッフは必須です';
  end if;
  if btrim(p_from_user_id) = btrim(p_to_user_id) then
    raise exception '変更元スタッフと変更先スタッフは異なるスタッフを指定してください';
  end if;
  if not exists (
    select 1 from public.users u
    where u.auth_user_id::text = p_actor_auth_id::text
      and lower(coalesce(u.system_role, '')) in ('manager', 'admin')
  ) then
    raise exception 'この操作を実行する権限がありません';
  end if;

  for v_shift in
    select s.*
    from public.shift s
    where (s.shift_start_date::date + coalesce(s.shift_start_time::time, time '00:00')) >= p_start_at
      and btrim(p_from_user_id) in (
        nullif(btrim(s.staff_01_user_id), ''), nullif(btrim(s.staff_02_user_id), ''), nullif(btrim(s.staff_03_user_id), '')
      )
    for update
  loop
    v_processed := v_processed + 1;
    v_entries := jsonb_build_array(
      jsonb_build_object('user_id', nullif(btrim(v_shift.staff_01_user_id), ''), 'role_code', v_shift.staff_01_role_code, 'attend_flg', false),
      jsonb_build_object('user_id', nullif(btrim(v_shift.staff_02_user_id), ''), 'role_code', v_shift.staff_02_role_code, 'attend_flg', coalesce(v_shift.staff_02_attend_flg, false)),
      jsonb_build_object('user_id', nullif(btrim(v_shift.staff_03_user_id), ''), 'role_code', v_shift.staff_03_role_code, 'attend_flg', coalesce(v_shift.staff_03_attend_flg, false))
    );
    v_target_exists := exists (
      select 1 from jsonb_array_elements(v_entries) e
      where e->>'user_id' = btrim(p_to_user_id)
    );
    v_next := '[]'::jsonb;
    v_seen := array[]::text[];
    for v_entry in select value from jsonb_array_elements(v_entries)
    loop
      v_user_id := v_entry->>'user_id';
      if v_user_id is null then
        continue;
      end if;
      -- A replacement that would duplicate an existing assignee removes the
      -- departing slot.  All remaining entries are then compacted in order.
      if v_user_id = btrim(p_from_user_id) then
        if v_target_exists then
          continue;
        end if;
        v_entry := jsonb_set(v_entry, '{user_id}', to_jsonb(btrim(p_to_user_id)));
        v_user_id := btrim(p_to_user_id);
      end if;
      if v_user_id = any(v_seen) then
        continue;
      end if;
      v_seen := array_append(v_seen, v_user_id);
      v_next := v_next || jsonb_build_array(v_entry);
    end loop;
    v_count := jsonb_array_length(v_next);
    if v_count = 0 then
      delete from public.shift where shift_id = v_shift.shift_id;
      v_deleted := v_deleted + 1;
    else
      update public.shift s set
        staff_01_user_id = v_next->0->>'user_id',
        staff_01_role_code = v_next->0->>'role_code',
        staff_02_user_id = case when v_count >= 2 then v_next->1->>'user_id' else null end,
        staff_02_role_code = case when v_count >= 2 then v_next->1->>'role_code' else null end,
        staff_02_attend_flg = case when v_count >= 2 then coalesce((v_next->1->>'attend_flg')::boolean, false) else false end,
        staff_03_user_id = case when v_count >= 3 then v_next->2->>'user_id' else null end,
        staff_03_role_code = case when v_count >= 3 then v_next->2->>'role_code' else null end,
        staff_03_attend_flg = case when v_count >= 3 then coalesce((v_next->2->>'attend_flg')::boolean, false) else false end,
        update_at = now()
      where s.shift_id = v_shift.shift_id;
      v_updated := v_updated + 1;
    end if;
  end loop;

  -- Weekly templates create future shifts.  Only active templates which can
  -- still produce a shift on/after the start date are changed in this same
  -- transaction; an expired or inactive template remains historical data.
  for v_template in
    select t.*
    from public.shift_weekly_template t
    where t.active
      and (t.effective_to is null or t.effective_to::date >= p_start_at::date)
      and btrim(p_from_user_id) in (
        nullif(btrim(t.staff_01_user_id), ''), nullif(btrim(t.staff_02_user_id), ''), nullif(btrim(t.staff_03_user_id), '')
      )
    for update
  loop
    v_weekly_processed := v_weekly_processed + 1;
    v_entries := jsonb_build_array(
      jsonb_build_object('user_id', nullif(btrim(v_template.staff_01_user_id), ''), 'role_code', v_template.staff_01_role_code, 'attend_flg', false),
      jsonb_build_object('user_id', nullif(btrim(v_template.staff_02_user_id), ''), 'role_code', v_template.staff_02_role_code, 'attend_flg', coalesce(v_template.staff_02_attend_flg, false)),
      jsonb_build_object('user_id', nullif(btrim(v_template.staff_03_user_id), ''), 'role_code', v_template.staff_03_role_code, 'attend_flg', coalesce(v_template.staff_03_attend_flg, false))
    );
    v_target_exists := exists (select 1 from jsonb_array_elements(v_entries) e where e->>'user_id' = btrim(p_to_user_id));
    v_next := '[]'::jsonb;
    v_seen := array[]::text[];
    for v_entry in select value from jsonb_array_elements(v_entries)
    loop
      v_user_id := v_entry->>'user_id';
      if v_user_id is null then continue; end if;
      if v_user_id = btrim(p_from_user_id) then
        if v_target_exists then continue; end if;
        v_entry := jsonb_set(v_entry, '{user_id}', to_jsonb(btrim(p_to_user_id)));
        v_user_id := btrim(p_to_user_id);
      end if;
      if v_user_id = any(v_seen) then continue; end if;
      v_seen := array_append(v_seen, v_user_id);
      v_next := v_next || jsonb_build_array(v_entry);
    end loop;
    v_count := jsonb_array_length(v_next);
    if v_count = 0 then
      delete from public.shift_weekly_template where template_id = v_template.template_id;
      v_weekly_deleted := v_weekly_deleted + 1;
    else
      update public.shift_weekly_template t set
        staff_01_user_id = v_next->0->>'user_id',
        staff_01_role_code = v_next->0->>'role_code',
        staff_02_user_id = case when v_count >= 2 then v_next->1->>'user_id' else null end,
        staff_02_role_code = case when v_count >= 2 then v_next->1->>'role_code' else null end,
        staff_02_attend_flg = case when v_count >= 2 then coalesce((v_next->1->>'attend_flg')::boolean, false) else false end,
        staff_03_user_id = case when v_count >= 3 then v_next->2->>'user_id' else null end,
        staff_03_role_code = case when v_count >= 3 then v_next->2->>'role_code' else null end,
        staff_03_attend_flg = case when v_count >= 3 then coalesce((v_next->2->>'attend_flg')::boolean, false) else false end
      where t.template_id = v_template.template_id;
      v_weekly_updated := v_weekly_updated + 1;
    end if;
  end loop;
  return query select v_processed, v_updated, v_deleted, 0, v_weekly_processed, v_weekly_updated, v_weekly_deleted;
end;
$function$

CREATE OR REPLACE FUNCTION public.roster_patch_shift_with_context(p_shift_id bigint, p_date date, p_start time without time zone, p_end time without time zone, p_update_at timestamp without time zone, p_target_col text, p_staff_id text, p_actor_user_id text DEFAULT NULL::text, p_request_path text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  col text;
  sql text;
begin
  perform set_config('app.actor_user_id', coalesce(p_actor_user_id,''), true);
  perform set_config('app.request_path', coalesce(p_request_path,''), true);

  if p_target_col is null or p_target_col = '' then
    col := null;
  elsif p_target_col in ('staff_01_user_id','staff_02_user_id','staff_03_user_id') then
    col := p_target_col;
  else
    raise exception 'invalid target_col: %', p_target_col;
  end if;

  if col is null then
    update public.shift
    set
      shift_start_date = p_date,
      shift_start_time = p_start,
      shift_end_time   = p_end,
      update_at        = p_update_at
    where shift_id = p_shift_id;
    return;
  end if;

  sql := format($f$
    update public.shift
    set
      shift_start_date = $1,
      shift_start_time = $2,
      shift_end_time   = $3,
      update_at        = $4,
      %I              = $5
    where shift_id = $6
  $f$, col);

  execute sql using p_date, p_start, p_end, p_update_at, p_staff_id, p_shift_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_audit_context(p_user_id text, p_action text DEFAULT NULL::text, p_trace_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  PERFORM set_config('app.current_user_id', COALESCE(p_user_id, ''), true);
  PERFORM set_config('app.current_action', COALESCE(p_action, ''), true);
  PERFORM set_config('app.current_trace_id', COALESCE(p_trace_id, ''), true);
END;
$function$

CREATE OR REPLACE FUNCTION public.shift_delete_with_context(p_shift_id bigint, p_actor_user_id text, p_request_path text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  perform set_config('app.actor_user_id', coalesce(p_actor_user_id,''), true);
  perform set_config('app.request_path',  coalesce(p_request_path,''), true);

  delete from public.shift
  where shift_id = p_shift_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.shift_direct_reassign(p_shift_id bigint, p_from_user_id text, p_to_user_id text, p_actor_auth_id text DEFAULT NULL::text, p_reason text DEFAULT 'leave_request_auto'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.shift%rowtype;
  v_swapped boolean := false;
  v_slot int := 0;  -- 1/2/3 のどこに from が入っているか
begin
  -- 1) 対象シフトをロック
  select * into v_row from public.shift where shift_id = p_shift_id for update;
  if not found then
    raise exception 'shift_id % not found', p_shift_id;
  end if;

  -- 2) from==to は no-op（ここで終了）
  if coalesce(p_from_user_id,'') = coalesce(p_to_user_id,'') then
    return jsonb_build_object('ok', true, 'noop', true, 'reason', p_reason);
  end if;

  -- 3) from が入っている枠を特定（完全一致）
  if v_row.staff_01_user_id = p_from_user_id then
    v_slot := 1;
  elsif v_row.staff_02_user_id = p_from_user_id then
    v_slot := 2;
  elsif v_row.staff_03_user_id = p_from_user_id then
    v_slot := 3;
  else
    raise exception 'from_user % not assigned on shift %', p_from_user_id, p_shift_id;
  end if;

  -- 4) 他枠に既に to が入っていたら重複防止で空に（from の枠は除外）
  if v_slot <> 1 and v_row.staff_01_user_id = p_to_user_id then v_row.staff_01_user_id := null; end if;
  if v_slot <> 2 and v_row.staff_02_user_id = p_to_user_id then v_row.staff_02_user_id := null; end if;
  if v_slot <> 3 and v_row.staff_03_user_id = p_to_user_id then v_row.staff_03_user_id := null; end if;

  -- 5) from 枠を to に置換
  if v_slot = 1 then
    v_row.staff_01_user_id := p_to_user_id; v_swapped := true;
  elsif v_slot = 2 then
    v_row.staff_02_user_id := p_to_user_id; v_swapped := true;
  else
    v_row.staff_03_user_id := p_to_user_id; v_swapped := true;
  end if;

  -- 6) 更新（列名は update_at）
  update public.shift
     set staff_01_user_id = v_row.staff_01_user_id,
         staff_02_user_id = v_row.staff_02_user_id,
         staff_03_user_id = v_row.staff_03_user_id,
         update_at        = now()
   where shift_id = p_shift_id;

  return jsonb_build_object('ok', v_swapped, 'reason', p_reason);
end $function$

CREATE OR REPLACE FUNCTION public.shift_direct_reassign(p_shift_id bigint, p_from_user_id text, p_to_user_id text, p_actor_auth_id text DEFAULT ''::text, p_reason text DEFAULT NULL::text, p_event_type text DEFAULT 'reject_shift'::text, p_penalty_level text DEFAULT 'minor'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_row public.shift%rowtype;
  v_before public.shift%rowtype;
  v_after public.shift%rowtype;
  v_swapped boolean := false;
  v_slot int := 0;
begin

  -- 対象シフトロック
  select *
    into v_row
  from public.shift
  where shift_id = p_shift_id
  for update;

  if not found then
    raise exception 'shift_id % not found', p_shift_id;
  end if;

  v_before := v_row;

  -- from==to は何もしない
  if coalesce(p_from_user_id,'') = coalesce(p_to_user_id,'') then
    return jsonb_build_object(
      'ok', true,
      'noop', true,
      'reason', p_reason
    );
  end if;

  -- from がどの枠か判定
  if v_row.staff_01_user_id = p_from_user_id then
    v_slot := 1;
  elsif v_row.staff_02_user_id = p_from_user_id then
    v_slot := 2;
  elsif v_row.staff_03_user_id = p_from_user_id then
    v_slot := 3;
  else
    raise exception
      'from_user % not assigned on shift %',
      p_from_user_id,
      p_shift_id;
  end if;

  -- 重複防止
  if v_slot <> 1
     and v_row.staff_01_user_id = p_to_user_id
  then
    v_row.staff_01_user_id := null;
  end if;

  if v_slot <> 2
     and v_row.staff_02_user_id = p_to_user_id
  then
    v_row.staff_02_user_id := null;
  end if;

  if v_slot <> 3
     and v_row.staff_03_user_id = p_to_user_id
  then
    v_row.staff_03_user_id := null;
  end if;

  -- 差し替え
  if v_slot = 1 then
    v_row.staff_01_user_id := p_to_user_id;
    v_swapped := true;

  elsif v_slot = 2 then
    v_row.staff_02_user_id := p_to_user_id;
    v_swapped := true;

  else
    v_row.staff_03_user_id := p_to_user_id;
    v_swapped := true;
  end if;

  -- 更新
  update public.shift
     set staff_01_user_id = v_row.staff_01_user_id,
         staff_02_user_id = v_row.staff_02_user_id,
         staff_03_user_id = v_row.staff_03_user_id,
         update_at = now()
   where shift_id = p_shift_id
   returning *
        into v_after;

  -- 監査ログ
  insert into public.audit_log (
    table_name,
    record_id,
    action,
    actor_user_id,
    request_path,
    changed_cols,
    before_row,
    after_row,
    change_reason,
    penalty_level,
    event_type,
    created_at
  )
  values (
    'shift',
    p_shift_id::text,
    'UPDATE',

    case
      when trim(coalesce(p_actor_auth_id,'')) = ''
      then null
      else p_actor_auth_id::uuid
    end,

    '/api/shift-reassign',

    array[
      'staff_01_user_id',
      'staff_02_user_id',
      'staff_03_user_id'
    ],

    to_jsonb(v_before),
    to_jsonb(v_after),

    p_reason,
    p_penalty_level,
    p_event_type,

    now()
  );

  return jsonb_build_object(
    'ok', true,
    'shift_id', p_shift_id,
    'reason', p_reason,
    'event_type', p_event_type,
    'penalty_level', p_penalty_level
  );

end;
$function$

CREATE OR REPLACE FUNCTION public.shift_direct_reassign(p_shift_id bigint, p_from_user_id text, p_to_user_id text, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_request_path text DEFAULT NULL::text, p_event_type text DEFAULT 'reject_shift'::text, p_penalty_level text DEFAULT 'minor'::text)
