    v_swapped := true;
  end if;

  update public.shift
     set staff_01_user_id = v_row.staff_01_user_id,
         staff_02_user_id = v_row.staff_02_user_id,
         staff_03_user_id = v_row.staff_03_user_id,
         update_at = now()
   where shift_id = p_shift_id
   returning * into v_after;

  insert into public.audit_log (
    table_name,
    record_id,
    action,
    actor_user_id,
    request_path,
    changed_cols,
    before_row,
    after_row,
    change_reason,
    penalty_level,
    event_type,
    created_at
  )
  values (
    'shift',
    p_shift_id::text,
    'UPDATE',
    p_actor_user_id,
    p_request_path,
    array['staff_01_user_id', 'staff_02_user_id', 'staff_03_user_id'],
    to_jsonb(v_before),
    to_jsonb(v_after),
    p_reason,
    p_penalty_level,
    p_event_type,
    now()
  );

  return jsonb_build_object(
    'ok', v_swapped,
    'reason', p_reason,
    'event_type', p_event_type,
    'penalty_level', p_penalty_level
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.shift_direct_reassign_uuid(p_shift_id uuid, p_from_user_id text, p_to_user_id text, p_actor_auth_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'leave_request_auto'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$declare
  v_row shift%rowtype;
  v_swapped boolean := false;
begin
  -- ロックして取得
  select * into v_row from shift where id = p_shift_id for update;
  if not found then
    raise exception 'shift % not found', p_shift_id;
  end if;

  -- 既に上長が他枠に入っていたら重複防止のため空にする
  if v_row.staff_01_user_id = p_to_user_id then v_row.staff_01_user_id := null; end if;
  if v_row.staff_02_user_id = p_to_user_id then v_row.staff_02_user_id := null; end if;
  if v_row.staff_03_user_id = p_to_user_id then v_row.staff_03_user_id := null; end if;

  -- from が入っている枠を to に置き換え
  if v_row.staff_01_user_id = p_from_user_id then
    v_row.staff_01_user_id := p_to_user_id; v_swapped := true;
  elsif v_row.staff_02_user_id = p_from_user_id then
    v_row.staff_02_user_id := p_to_user_id; v_swapped := true;
  elsif v_row.staff_03_user_id = p_from_user_id then
    v_row.staff_03_user_id := p_to_user_id; v_swapped := true;
  else
    raise exception 'from_user % not assigned on shift %', p_from_user_id, p_shift_id;
  end if;

  update shift
     set staff_01_user_id = v_row.staff_01_user_id,
         staff_02_user_id = v_row.staff_02_user_id,
         staff_03_user_id = v_row.staff_03_user_id,
         updated_at       = now()
   where id = p_shift_id;

  -- 任意：監査ログ
  insert into shift_assignment_logs
    (shift_id, from_user_id, to_user_id, changed_by_auth_id, reason, created_at)
  values
    (p_shift_id, p_from_user_id, p_to_user_id, p_actor_auth_id, p_reason, now());

  return jsonb_build_object('ok', v_swapped);
end$function$

CREATE OR REPLACE FUNCTION public.shifts_delete_with_context(p_shift_ids bigint[], p_actor_user_id text, p_request_path text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform set_config('app.actor_user_id', coalesce(p_actor_user_id,''), true);
